+
+Value Value::none()
+{
+    return Value{};
+}
+
+Value Value::string_value(std::string value)
+{
+    Value result;
+    result.kind = Kind::String;
+    result.string = std::move(value);
+    return result;
+}
+
+Value Value::integer_value(std::int64_t value)
+{
+    Value result;
+    result.kind = Kind::Integer;
+    result.integer = value;
